function gtByFile(name){return (window.POKESLEEP_GT30||[]).find(x=>x.file===name)||null;}
function eqArr(a,b){return Array.isArray(a)&&Array.isArray(b)&&a.length===b.length&&a.every((x,i)=>x===b[i]);}
function benchmarkRows(){
 const out=[];
 for(const r of results){
   const g=gtByFile(r.file);if(!g)continue;
   const p=r.parsed,c=r.classification;
   const species=c.candidates.length===1?c.candidates[0]:'';
   const nickPre=p.nicknameBeforePaddle??p.nickname;
   const paddleText=p.nicknamePaddle?.ok?cleanNick(p.nicknamePaddle.cleanedText||p.nicknamePaddle.text):'';
   out.push({
    file:r.file,
    structured:(p.level===g.level&&p.sp===g.sp&&p.helpSeconds===g.helpSeconds&&p.carry===g.carry&&p.skillLevel===g.skillLevel&&mainSkillForOutput(p,r.classification)===g.mainSkill&&p.nature===g.nature&&eqArr(p.subs.map(x=>x.value),g.subskills)),
    species:species===g.expected,
    foodSlots:r.foods.map((x,i)=>x.name===g.foods[i]),
    nicknameTesseract:nickPre===g.nickname,
    nicknameFinal:p.nickname===g.nickname,
    paddleAttempted:!!p.nicknamePaddle,
    paddleOk:!!p.nicknamePaddle?.ok,
    nicknamePaddle:paddleText===g.nickname,
    paddleText:paddleText,
    expectedNickname:g.nickname,
    paddleConfidence:p.nicknamePaddle?.confidence??null,
    paddleWallMs:p.nicknamePaddle?.wallMs??null,
    elapsedMs:r.elapsedMs,
    nicknameNeedsReview:!!p.nicknameNeedsReview
   });
 }
 return out;
}
function benchmarkSummary(){
 const rows=benchmarkRows(),n=rows.length;if(!n)return null;
 const sum=k=>rows.filter(x=>x[k]).length;
 const food=rows.reduce((a,x)=>a+x.foodSlots.filter(Boolean).length,0),foodTotal=rows.reduce((a,x)=>a+x.foodSlots.length,0);
 const paddled=rows.filter(x=>x.paddleAttempted),paddleOk=paddled.filter(x=>x.paddleOk),paddleCorrect=paddled.filter(x=>x.nicknamePaddle);
 const totalMs=rows.reduce((a,x)=>a+(x.elapsedMs||0),0);
 return {matched:n,structured:`${sum('structured')}/${n}`,species:`${sum('species')}/${n}`,food:`${food}/${foodTotal}`,nicknameTesseract:`${sum('nicknameTesseract')}/${n}`,nicknameFinal:`${sum('nicknameFinal')}/${n}`,paddleAttempted:paddled.length,paddleSucceeded:paddleOk.length,paddleCorrect:`${paddleCorrect.length}/${paddled.length||0}`,reviewRemaining:rows.filter(x=>x.nicknameNeedsReview).length,totalMs,avgMs:Math.round(totalMs/n),rows};
}
function renderBenchmark(){
 const el=$('#benchSummary');if(!el)return;const b=benchmarkSummary();
 if(!b){el.innerHTML='既知テスト画像が含まれると、ここに自動採点結果を表示します。';return;}
 el.innerHTML=`<div><b>${b.matched}枚を自動採点</b></div>`+
 `<div>構造化OCR: <b>${b.structured}</b> / 種族: <b>${b.species}</b> / 食材: <b>${b.food}</b></div>`+
 `<div>ニックネーム Tesseract系: <b>${b.nicknameTesseract}</b> → 最終: <b>${b.nicknameFinal}</b></div>`+
 `<div>Paddle実行: <b>${b.paddleAttempted}</b>件 / 成功: <b>${b.paddleSucceeded}</b>件 / 正解: <b>${b.paddleCorrect}</b> / 要確認残り: <b>${b.reviewRemaining}</b></div>`+
 `<div>合計処理時間: <b>${(b.totalMs/1000).toFixed(1)}秒</b> / 1枚平均: <b>${(b.avgMs/1000).toFixed(2)}秒</b></div>`+
 (b.matched<30?'<div class="warn">既知30枚の一部だけ選択されています。</div>':'');
}
